import * as http from 'node:http';
import * as net from 'node:net';
async function main(): Promise<void> {
  const h = http.createServer((req: any, res: any) => { res.end('http-ok'); });
  const n = net.createServer((sock: any) => { sock.end('net-ok'); });
  await new Promise<void>((r) => n.listen(0, '127.0.0.1', () => r()));
  console.log('net port', typeof (n.address() as any).port);
  n.close();
  await new Promise<void>((r) => h.listen(0, '127.0.0.1', () => r()));
  const r = await fetch('http://127.0.0.1:' + (h.address() as any).port + '/');
  console.log(await r.text());
  h.close();
}
